package maxsubarray

import "testing"

func TestClassic(t *testing.T) {
	if got := MaxSubarray([]int{-2, 1, -3, 4, -1, 2, 1, -5, 4}); got != 6 {
		t.Fatalf("got %d, want 6", got)
	}
}

func TestSingle(t *testing.T) {
	if got := MaxSubarray([]int{5}); got != 5 {
		t.Fatalf("got %d, want 5", got)
	}
}

func TestAllPositive(t *testing.T) {
	if got := MaxSubarray([]int{1, 2, 3, 4}); got != 10 {
		t.Fatalf("got %d, want 10", got)
	}
}

func TestAllNegative(t *testing.T) {
	if got := MaxSubarray([]int{-3, -1, -2}); got != -1 {
		t.Fatalf("got %d, want -1", got)
	}
}

func TestMixed(t *testing.T) {
	if got := MaxSubarray([]int{5, 4, -1, 7, 8}); got != 23 {
		t.Fatalf("got %d, want 23", got)
	}
}

func TestTwo(t *testing.T) {
	if got := MaxSubarray([]int{-2, -1}); got != -1 {
		t.Fatalf("got %d, want -1", got)
	}
}
